styles=[('Display','Instrument Serif',96,56,400,1.02,'-.025em','Memory, made legible.'),('H1 · Page title','Instrument Serif',72,44,400,1.06,'-.02em','Understand the record.'),('H2 · Section title','Instrument Serif',52,36,400,1.1,'-.015em','Every change has a source.'),('H3 · Feature title','Instrument Serif',34,28,400,1.15,'-.01em','Follow the evidence.'),('H4 · Panel title','Inter',24,22,500,1.25,'-.01em','Review the current version'),('H5 · Subsection','Inter',20,20,500,1.35,'0em','Known destinations'),('H6 · Field group','Inter',16,16,600,1.4,'0em','Tenant and purpose'),('Lead · Introduction','Inter',22,20,400,1.5,'-.01em','See what changed, why it changed and which systems were checked.'),('Body · Reading','Inter',18,16,400,1.6,'0em','A useful record includes its source, its scope and a clear account of what remains unknown.'),('UI · Nav / button','Inter',15,15,500,1.3,'0em','Map your memory deletion paths'),('Data · Table / number','Inter',14,14,400,1.45,'0em','C-012   ·   08 Oct 2026   ·   Version 2'),('Caption · Supporting','Inter',13,13,400,1.5,'0em','Synthetic example. Backup status remains unverified.'),('Eyebrow · Category','Inter',12,12,500,1.4,'.1em','MEMORY REVIEW'),('Quote · Editorial','Instrument Serif',36,28,400,1.2,'-.01em','“A receipt should state its limits.”')]
rows=''.join(f'''<div class="type-row"><div class="type-meta"><strong>{label}</strong><span>{family} · {weight}</span><span><b class="size-desktop">{desk}px</b><b class="size-mobile">{mob}px</b> / {lh} line height</span><span>{tracking} tracking · 0 word spacing</span></div><div class="type-example" style="--sample-desktop:{desk}px;--sample-mobile:{mob}px;font-family:'{family}',{('serif' if family=='Instrument Serif' else 'sans-serif')};font-weight:{weight};line-height:{lh};letter-spacing:{tracking};{'font-variant-numeric:tabular-nums;' if label.startswith('Data') else ''}">{sample}</div></div>''' for label,family,desk,mob,weight,lh,tracking,sample in styles)
