t=json.loads((p/'tokens/tokens.json').read_text());t['typography']['styles']={r[0].split(' · ')[0].lower():{'fontFamily':r[1],'desktopPx':r[2],'mobilePx':r[3],'weight':r[4],'lineHeight':r[5],'letterSpacing':r[6],'wordSpacing':'normal'} for r in styles};t['shadows']['overlay']='0 32px 80px #1f26172e';t['spacingRoles']={'eyebrowToHeading':12,'headingToBody':24,'paragraphGap':16,'bodyToAction':32,'cardPaddingDesktop':32,'cardPaddingMobile':20,'sectionDesktop':96,'sectionTablet':64,'sectionMobile':56,'chapterLarge':128};(p/'tokens/tokens.json').write_text(json.dumps(t,indent=2))
c='\n:root {\n --shadow-overlay:0 32px 80px #1f26172e;\n --gap-eyebrow-heading:12px; --gap-heading-body:24px; --gap-paragraph:16px; --gap-body-action:32px;\n --padding-card:32px; --section-space:96px; --page-margin:32px;\n'
for label,fam,d,m,w,lh,tr,example in styles:
 role=label.split(' · ')[0].lower();c+=f' --text-{role}-size:{d}px; --text-{role}-weight:{w}; --text-{role}-leading:{lh}; --text-{role}-tracking:{tr};\n'
c+='}\n@media(min-width:768px) and (max-width:1199px){:root{--section-space:64px;}}\n@media(max-width:767px){:root{--padding-card:20px;--section-space:56px;--page-margin:20px;\n'
for label,fam,d,m,w,lh,tr,example in styles:c+=f' --text-{label.split(" · ")[0].lower()}-size:{m}px;\n'
c+='}}\n'
with (p/'tokens/tokens.css').open('a') as f:f.write(c)
print('Added complete visible foundation specimens and matching tokens.')
